def find_length(string):
    n = len(string)
    max_diff = 0
    for i in range(n):
        count0 = 0
        count1 = 0
        for j in range(i, n):
            if string[j] == '0':
                count0 += 1
            else:
                count1 += 1
            current_diff = count0 - count1
            if current_diff > max_diff:
                max_diff = current_diff
    return max_diff if max_diff else 0

